'use strict';
(()=>{
const header=document.querySelector('body>header');if(!header)return;
const bell=document.createElement('button');bell.type='button';bell.className='notification-toggle';bell.setAttribute('aria-label','Уведомления');bell.setAttribute('aria-controls','notifications-page');bell.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><span class="notification-count" hidden></span>';header.insertBefore(bell,header.querySelector('.account'));
const page=document.createElement('main');page.id='notifications-page';page.hidden=true;
page.innerHTML=`<div class="breadcrumb">Рабочее пространство / Уведомления</div><div class="heading"><div><h1>Уведомления</h1><p>Ошибки, остановки и согласование рассылок</p></div><button class="outline" data-refresh>Обновить</button></div><div class="demo"><span>Только внутри приложения. SMTP и реальная отправка выключены. Прочтение учитывается отдельно для каждого пользователя.</span></div><section class="panel"><form class="notification-filters"><label>Показывать<select name="state"><option value="all">Все уведомления</option><option value="unread">Непрочитанные и актуальные</option></select></label><label>Тип<select name="kind"><option value="">Все типы</option><option value="error">Ошибки</option><option value="stop">Остановки</option><option value="approval">Согласование</option></select></label><button class="outline">Применить</button></form><div class="notification-tools"><p data-total></p><button class="outline" data-read-page>Отметить страницу прочитанной</button></div><p role="status" aria-live="polite" data-status></p><div class="notification-items"></div><div class="notification-tools"><button class="outline" data-prev>Назад</button><span data-pagination></span><button class="outline" data-next>Далее</button></div></section>`;
document.body.append(page);
const style=document.createElement('style');style.textContent=`.notification-toggle{position:relative;display:flex;align-items:center;justify-content:center;flex:none;width:38px;min-height:36px;margin-left:auto;background:#f1f7fc;border:1px solid #d9e5ef;border-radius:6px;color:#167ab2;padding:7px}.notification-toggle svg{width:18px;height:18px}.notification-toggle+.account{margin-left:0}.notification-count{position:absolute;top:-6px;right:-8px;border-radius:10px;background:#dd5947;color:white;padding:1px 5px;min-width:18px;font-size:10px;line-height:16px}.notification-filters{display:flex;gap:12px;flex-wrap:wrap;align-items:end}.notification-filters label{margin:0;min-width:180px}.notification-filters select{display:block;width:100%;margin-top:6px}.notification-tools{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin:18px 0}.notification-items{display:grid;gap:12px}.notification-item{padding:16px;border:1px solid #dce4ec;border-left:3px solid #bed0df;border-radius:7px;background:white;overflow-wrap:anywhere}.notification-item.unread{background:#f4faff;border-left-color:#0795e9}.notification-item[data-kind=error]{border-left-color:#ca5a42}.notification-item[data-kind=stop]{border-left-color:#b98725}.notification-item h2{font-size:15px;margin:0 0 6px}.notification-item p{margin:7px 0}.notification-meta{font-size:11px;color:#687c95}.notification-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}#notifications-page button{width:auto;min-height:36px;margin-top:0}#notifications-page input,#notifications-page select{font-size:12px}#notifications-page [data-status]{color:#825525}#notifications-page{min-width:0}@media(max-width:700px){.notification-toggle{width:34px;min-height:40px;padding:6px}header{gap:8px!important}.notification-filters{display:grid;grid-template-columns:1fr;gap:12px}.notification-filters label{min-width:0}#notifications-page select{font-size:16px;min-height:44px}.notification-actions button{flex:1 1 100%}#notifications-page button{min-height:44px}.notification-item{padding:13px}.notification-tools>[data-read-page]{width:100%}#notifications-page h1{font-size:24px}.notification-toggle+.account{max-width:58%}}`;document.head.append(style);
const $=s=>page.querySelector(s);let items=[],number=1,pages=1,busy=false,sequence=0,timer;
function text(tag,value){const n=document.createElement(tag);n.textContent=value??'';return n;}
function badge(value){const n=bell.querySelector('span');n.hidden=!value;n.textContent=value>99?'99+':String(value);bell.setAttribute('aria-label',`Уведомления: ${value} непрочитанных`);bell.title=`Непрочитанных актуальных уведомлений: ${value}`;}
async function request(path,options={}){const token=document.cookie.split('; ').find(v=>v.startsWith('sales_csrftoken='))?.split('=')[1]||'';const response=await fetch(path,{cache:'no-store',...options,headers:{'X-CSRFToken':token,...options.headers}});let data;try{data=await response.json();}catch{throw new Error('Не удалось загрузить уведомления. Повторите обновление.');}if(!response.ok){if(response.status===401)bell.hidden=true;throw new Error(data.error||'Ошибка обновления уведомлений.');}bell.hidden=false;return data;}
function controls(){for(const b of page.querySelectorAll('button'))b.disabled=busy;$('[data-prev]').disabled=busy||number<=1;$('[data-next]').disabled=busy||number>=pages;$('[data-read-page]').disabled=busy||!items.some(n=>!n.read);}
function render(data){items=data.items;number=data.pagination.page;pages=data.pagination.pages;badge(data.unread);$('[data-total]').textContent=`Найдено: ${data.pagination.total}. Непрочитанных актуальных: ${data.unread}.`;$('[data-pagination]').textContent=`${number} / ${pages}`;const host=$('.notification-items');host.replaceChildren();if(!items.length)host.append(text('p','Нет уведомлений по выбранным условиям.'));
for(const item of items){const box=document.createElement('article');box.className='notification-item'+(!item.read?' unread':'');box.dataset.kind=item.kind;box.append(text('h2',item.title));const meta=text('p',`${new Date(item.updated_at).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'})} · ${item.read?'Прочитано':'Не прочитано'}${item.resolved?' · Уже обработано':''}`);meta.className='notification-meta';box.append(meta,text('p',item.message));if(item.target.object_id)box.append(text('small',`${{campaign:'Рассылка',queue:'Очередь',rehearsal:'Репетиция',simulation:'Имитация сценария',scenario:'Сценарий',source:'Источник'}[item.target.object_type]||'Объект'} #${item.target.object_id}`));const actions=document.createElement('div');actions.className='notification-actions';const open=text('button',item.target.type==='approval'?'Открыть согласование':item.target.type==='queue'?'Открыть очередь':item.target.type==='source'?'Открыть сбор данных':['rehearsal','simulation'].includes(item.target.type)?'Открыть запуск':'Открыть журнал');open.className='outline';open.onclick=()=>mutate(async()=>{await mark([item],'read');await navigate(item.target);});const read=text('button',item.read?'Отметить непрочитанным':'Отметить прочитанным');read.className='outline';read.onclick=()=>mutate(()=>mark([item],item.read?'unread':'read'));actions.append(open,read);box.append(actions);host.append(box);}controls();}
async function navigate(target){if(target.type==='rehearsal'&&window.CampaignRehearsal?.openRun){await window.CampaignRehearsal.openRun(target.object_id);sessionStorage.removeItem('notifications-open');return;}if(target.type==='simulation'&&window.AutomationSimulation?.openRun){await window.AutomationSimulation.openRun(target.object_id);sessionStorage.removeItem('notifications-open');return;}if(target.type==='approval'&&window.CampaignApproval){await window.CampaignApproval.open(target.campaign_id);return;}if(target.type==='queue'&&window.CampaignQueue){await window.CampaignQueue.open(target.campaign_id);return;}if(target.type==='source'){const button=[...document.querySelectorAll('aside nav button')].find(b=>b.textContent.trim()==='Сбор данных');if(button&&!button.disabled){button.click();return;}}if(window.ActionJournal?.openTarget){window.ActionJournal.openTarget(target);page.hidden=true;sessionStorage.removeItem('notifications-open');return;}throw new Error('Раздел ещё загружается. Повторите переход через несколько секунд.');}
async function load(){const id=++sequence;const params=new URLSearchParams({state:$('[name=state]').value,kind:$('[name=kind]').value,page:String(number)});const data=await request('/api/notifications?'+params);if(id===sequence)render(data);}
async function mark(selected,action){++sequence;const data=await request('/api/notifications',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,items:selected.map(n=>({id:n.id,version:n.version}))})});badge(data.unread);await load();}
async function mutate(action){if(busy)return;busy=true;controls();$('[data-status]').textContent='';try{await action();}catch(e){$('[data-status]').textContent=e.message;}finally{busy=false;controls();}}
function open(){window.scrollTo(0,0);document.dispatchEvent(new Event('notifications-opened'));document.querySelectorAll('body>main').forEach(m=>m.hidden=true);page.hidden=false;document.querySelectorAll('aside nav button').forEach(b=>b.classList.remove('active'));document.title='Уведомления';sessionStorage.setItem('notifications-open','1');number=1;mutate(load);}
bell.onclick=open;$('[data-refresh]').onclick=()=>mutate(load);$('[data-read-page]').onclick=()=>mutate(()=>mark(items.filter(n=>!n.read),'read'));$('.notification-filters').onsubmit=e=>{e.preventDefault();number=1;mutate(load);};$('[data-prev]').onclick=()=>{number--;mutate(load);};$('[data-next]').onclick=()=>{number++;mutate(load);};
document.querySelector('aside nav')?.addEventListener('click',e=>{if(e.target.closest('button:not(:disabled)')){page.hidden=true;sessionStorage.removeItem('notifications-open');}});
async function poll(){clearTimeout(timer);if(!document.hidden&&!busy){try{if(page.hidden){const data=await request('/api/notifications?state=unread');badge(data.unread);}else await load();}catch(e){bell.title='Не удалось обновить уведомления';if(!page.hidden)$('[data-status]').textContent=e.message;}}timer=setTimeout(poll,30000);}
document.addEventListener('campaign-approval-changed',()=>{if(!busy)poll();});window.addEventListener('pagehide',()=>clearTimeout(timer));window.addEventListener('pageshow',()=>poll());
try{if(sessionStorage.getItem('notifications-open')==='1')open();}catch{}poll();
})();
